1: import { Component } from "@angular/core";
2: import { MatDialog } from "@angular/material/dialog";
3: import { environment } from "src/environments/environment";
4: import { ModalMotivosRechazoComponent } from "../revision-jefe/modal-motivos-rechazo/modal-motivos-rechazo.component";
5: import { ModalAprobacionSecretarioComponent } from "./modal-aprobacion-secretario/modal-aprobacion-secretario.component";
6: import { ActivatedRoute, Router } from "@angular/router";
7: import { lastValueFrom, forkJoin } from 'rxjs';
8: import { PlanAnualAuditoriaService } from "src/app/core/services/plan-anual-auditoria.service";
9: import { UserService } from "src/app/core/services/user.service";
10: import { NuxeoService } from "src/app/core/services/nuxeo.service";
11: import { ReferenciaPdfService } from "src/app/core/services/referencia-pdf.service";
12: import { DescargaService } from "src/app/shared/services/descarga.service";
13: import { TercerosService } from "src/app/shared/services/terceros.service";
14: import { RolService } from "src/app/core/services/rol.service";
15: import { ParametrosUtilsService } from "src/app/shared/services/parametros.service";
16: import { DocumentoUtils, REFRESHABLES } from "../consulta-plan.auditoria.utils";
