18: 
19: @Component({
20:     selector: "app-revision-secretario",
21:     templateUrl: "./revision-secretario.component.html",
22:     styleUrl: "./revision-secretario.component.css",
23:     standalone: false
24: })
25: export class RevisionSecretarioComponent {
26:   selectedTab: number = 0;
27:   planAuditoriaId: string = "";
28:   estadoIdActual: number | null = null;
29:   mostrarBotones: boolean = true;
30: 
31:   constructor(
32:     public readonly dialog: MatDialog,
33:     private readonly planAuditoriaService: PlanAnualAuditoriaService,
34:     private readonly referenciaPdfService: ReferenciaPdfService,
35:     private readonly nuxeoService: NuxeoService,
36:     private readonly userService: UserService,
37:     private readonly router: Router,
38:     private readonly route: ActivatedRoute,
39:     private readonly descargaService: DescargaService,
40:     private readonly tercerosService: TercerosService,
41:     private readonly rolService: RolService,
42:     private readonly parametrosUtilsService: ParametrosUtilsService,
43:     private readonly documentoUtils: DocumentoUtils,
44:   ) { }
45: 
46:   botonSeleccionado: string = "formato";
47:   documentos: { base64: string; tipo_id: number }[] = [];
48:   documentosPorTab: { [key: number]: string } = {};
49:   tabs: TabDocumento[] = [];
50:   roles: string[] = [];
51:   usuarioId: any;
52:   vigenciaNombre: string = "";
53:   
54:   async ngOnInit() {
55:     console.debug("Inicializando RevisionSecretarioComponent...");
56:     this.planAuditoriaId = this.route.snapshot.paramMap.get("id") ?? '';
57:     this.roles = this.rolService.getRoles();
58:     this.obtenerVigenciaActual();
59:     this.obtenerEstadoActual();
60:     try {
61:       await this.renderizarDocumentos();
62:     } catch (error) {
63:       console.log("no se genero el base 64");
64:     }
65:     this.userService.getPersonaId().then((usuarioId) => {
66:       this.usuarioId = usuarioId;
67:     });
68:   }
69: 
70:   obtenerVigenciaActual(): void {
71:     forkJoin({
72:       plan: this.planAuditoriaService.get(`plan-auditoria/${this.planAuditoriaId}`),
73:       vigencias: this.parametrosUtilsService.getVigencias(),
74:     }).subscribe({
75:       next: ({ plan, vigencias }: any) => {
76:         const vigenciaId = plan?.Data?.vigencia_id;
77:         const vigenciaNombre = vigencias?.find((v: any) => v.Id === vigenciaId)?.Nombre ?? '';
78:         this.vigenciaNombre = vigenciaNombre ?? '';
79:       },
80:       error: (error) => {
81:         console.error("Error al obtener la vigencia:", error);
82:       }
83:     });
84:   }
85: 
86:   obtenerEstadoActual(): void {
87:     const callbacks = {
88:       [REFRESHABLES.FORMATO_PAA_ACTUALIZADO]: () =>
89:         this.renderizarDocumentos(),
90:     };
91:     this.planAuditoriaService
92:       .get(`estado?query=plan_auditoria_id:${this.planAuditoriaId},actual:true`)
93:       .subscribe({
94:         next: (response: any) => {
95:           const estadoActual = response?.Data?.[0];
96:           this.estadoIdActual = estadoActual?.estado_id ?? null;
97:           this.mostrarBotones =
98:               this.estadoIdActual === environment.PLAN_ESTADO.EN_REVISION_SECRETARIO_ID;
99: 
100:           this.tabs = this.documentoUtils.getTabsVerDocumentos(this.planAuditoriaId, this.estadoIdActual ?? 0, this.roles, callbacks);
101:         },
102:         error: (error) => {
103:           console.error("Error al obtener el estado actual:", error);
104:           this.mostrarBotones = false;
105:           this.tabs = this.documentoUtils.getTabsVerDocumentos(this.planAuditoriaId, 0, this.roles, callbacks);
106:         }
107:       });
108:   }
109: 
110:   abrirModalRechazo(): void {
111:     if (!this.mostrarBotones) return;
112: 
113:     this.tercerosService.getAuthenticatedUserTerceroIdentification().subscribe({
114:       next: (tercero) => {
115:         this.dialog.open(ModalMotivosRechazoComponent, {
116:           width: "50%",
117:           data: {
118:             usuarioId: this.usuarioId,
119:             planAuditoriaId: this.planAuditoriaId,
120:             rolRemitente: "Secretario Auditor",
121:             nombreRemitente: tercero.NombreCompleto,
122:             vigencia: null,
123:           },
124:         });
125:       },
126:       error: (err) => {
127:         console.warn("Error obteniendo datos del Secretario para el modal:", err);
128:         this.dialog.open(ModalMotivosRechazoComponent, {
129:           width: "50%",
130:           data: {
131:             usuarioId: this.usuarioId,
132:             planAuditoriaId: this.planAuditoriaId,
133:             rolRemitente: "Secretario Auditor",
134:             nombreRemitente: "Secretario Auditor",
135:             vigencia: null,
136:           },
137:         });
138:       }
139:     });
140:   }
141: 
142:   abrirModalEnviar(): void {
143:     if (!this.mostrarBotones) return;
144:     this.dialog.open(ModalAprobacionSecretarioComponent, {
145:       width: "600px",
146:       data: {
147:         usuarioId: this.usuarioId,
148:         usuarioRol: environment.ROL.SECRETARIO,
149:         planAuditoriaId: this.planAuditoriaId,
150:       },
151:     });
152:   }
153: 
154:   selectTab(index: number) {
155:     this.selectedTab = index;
156:   }
157: 
158:   regresarRuta() {
159:     this.router.navigate([`/programacion/plan-auditoria`]);
160:   }
161: 
162:   async renderizarDocumentos() {
163:     try {
164:       this.documentos = [];
165:       this.documentosPorTab = {};
166: 
167:       const enlacesConTipo = await lastValueFrom(
168:         this.referenciaPdfService.consultarDocumentos(this.planAuditoriaId)
169:       );
170: 
171:       const enlaces = enlacesConTipo.map((doc) => doc.nuxeo_enlace);
172:       const base64Files = await this.nuxeoService.obtenerPorUUIDs(enlaces);
173: 
174:       enlacesConTipo.forEach((doc, index) => {
175:         const base64 = base64Files[index];
176:         this.documentos.push({ base64, tipo_id: doc.tipo_id });
177:       });
178: 
179:       const tabHolders = this.tabs.map((tab, i) => ({ idx: i, tab: tab }));
180:       this.documentos.forEach((doc) => {
181:         const holderIdx = tabHolders.findIndex(holder => holder.tab.tipoId === doc.tipo_id);
182:         if (holderIdx !== -1) {
183:           this.documentosPorTab[tabHolders[holderIdx].idx] = doc.base64;
184:           tabHolders.splice(holderIdx, 1);
185:         }
186:       });
187: 
188:     } catch (error) {
189:       console.error("Error al renderizar los documentos:", error);
190:     }
191:   }
192: 
193:   async descargarTodo() {
194:     try {
195:       const suffix = this.vigenciaNombre ? `${this.vigenciaNombre.replace(/\s+/g, '-')}` : '';
196:       await this.descargaService.descargarMultiplesArchivos(
197:         this.documentos,
198:         `documentosPAA-${suffix}.zip`,
199:         suffix
200:       );
