657:   async cargarRestricionesGrupoEstudio(
658:     elementMoved: CardDetalleCarga
659:   ): Promise<void> {
660:     const espacioAcademicoId = elementMoved?.idEspacioAcademico!;
661:     if (!espacioAcademicoId || espacioAcademicoId === "NA") {
662:       return;
663:     }
664: 
665:     const periodoId = this.Data.vigencia;
666:     const resEspacio: any = await this.espacioAcademicoService
667:       .get(`espacio-academico/${espacioAcademicoId}`)
668:       .toPromise();
669: 
670:     const grupoEstudioId = resEspacio.Data?.grupo_estudio_id;
671: 
672:     if (!grupoEstudioId || grupoEstudioId === 0 || grupoEstudioId === "0") {
