678:         `colocacion-espacio-academico/sin-detalles?grupo-estudio-id=${grupoEstudioId}&periodo-id=${periodoId}`
679:       )
680:       .toPromise();
681: 
682:     if (resColocacion.Data && resColocacion.Data.length > 0) {
683:       this.agregarRestriccionesAlHorario(resColocacion.Data, {
684:         grupoEstudio: true,
685:       });
686:     }
