693:     colocaciones.forEach((element: any) => {
694:       const ocupado: any = {
695:         id: element._id,
696:         horas: element.ColocacionEspacioAcademico.horas,
697:         estado: this.estado.ubicado,
698:         dragPosition: element.ColocacionEspacioAcademico.finalPosition,
699:         prevPosition: element.ColocacionEspacioAcademico.finalPosition,
700:         finalPosition: element.ColocacionEspacioAcademico.finalPosition,
701:         //se pone true dependiendo del tipo de restriccion
702:         grupoEstudio: options.grupoEstudio || false,
703:         espacioFisico: options.espacioFisico || false,
704:       };
705:       if (
706:         !this.listaCargaLectiva.some(
707:           (carga) => carga.idColocacionEspacioAcademico === element._id
708:         )
709:       ) {
710:         const exists = this.listaRestriccionesHorario.some(
711:           (restriccion) => restriccion.id === ocupado.id
712:         );
713: 
714:         if (!exists) {
715:           const coord = this.getPositionforMatrix(ocupado);
716:           this.changeStateRegion(coord.x, coord.y, ocupado.horas, true);
717:           this.listaRestriccionesHorario.push(ocupado);
718:         }
719:       }
720:     });
