8: import { ROLES } from "src/app/models/diccionario";
9: import { MatPaginator } from "@angular/material/paginator";
10: import { MatTableDataSource } from "@angular/material/table";
11: import { FormGroup, FormBuilder, Validators, FormArray } from "@angular/forms";
12: import { EvaluacionDocenteService } from "src/app/services/evaluacion-docente-crud.service";
13: import { ParametrosService } from "src/app/services/parametros.service";
14: import {
15:   MAT_DIALOG_DATA,
16:   MatDialog,
17:   MatDialogRef,
18: } from "@angular/material/dialog";
19: 
20: @Component({
21:   selector: "app-definir-escalas",
22:   templateUrl: "./definir-escalas.component.html",
23:   styleUrls: ["./definir-escalas.component.scss"],
24: })
25: export class DefinirEscalasComponent implements OnInit {
26:   tipoEscala = "";
27:   escalas: any[] = [];
28:   tiposInput: any[] = [];
29:   ROLES = ROLES;
30:   isCreating = false;
31:   activeTab = 0;
32:   isViewingScale = false;
33:   escalaSeleccionada: any = {};
34:   previsualizacionActiva = false;
35:   ejemploPregunta = "";
36:   showMultipleOptions = false;
37: 
38:   valores: number[] = [1, 2, 3, 4, 5];
39:   opcionesPorDefecto: string[] = [
40:     "INSUFICIENTE",
41:     "NECESITA MEJORAR",
42:     "BUENO",
43:     "SOBRESALIENTE",
44:     "EXCELENTE",
45:   ];
46: 
47:   tipoCamposMap: { [key: string]: number } = {
48:     Textarea: 4674,
49:     Radio: 4668,
50:     ArchivoAnexo: 6686,
51:     LinkNuxeo: 4672,
52:   };
53: 
54:   displayedColumns: string[] = ["Pregunta", "TipoEscala", "Estado", "Acciones"];
55:   dataSource!: MatTableDataSource<any>;
56: 
57:   @ViewChild(MatPaginator) paginator!: MatPaginator;
58: 
59:   formularioEscala!: FormGroup;
60: 
61:   constructor(
62:     private readonly fb: FormBuilder,
63:     private readonly evaluacionDocenteService: EvaluacionDocenteService,
64:     private readonly parametrosService: ParametrosService,
65:     public dialog: MatDialog,
66:     private readonly cdr: ChangeDetectorRef
67:   ) {}
68: 
69:   ngOnInit(): void {
70:     this.inicializarFormulario();
71:     this.cargarEscalas();
72:     this.obtenerTiposInput();
73:   }
74: 
75:   inicializarFormulario() {
76:     this.formularioEscala = this.fb.group({
77:       label: ["", Validators.required],
78:       tipoCampo: ["", Validators.required],
79:       opciones: this.fb.array([]),
80:     });
81:     this.agregarOpcionesPorDefecto();
82:   }
83: 
84:   get opciones(): FormArray {
85:     return this.formularioEscala.get("opciones") as FormArray;
86:   }
87: 
88:   agregarOpcionesPorDefecto() {
89:     this.opcionesPorDefecto.forEach((opcion, index) => {
90:       this.opciones.push(
91:         this.fb.group({
92:           opcion: [opcion, Validators.required],
93:           valorControl: [
94:             this.valores[index],
95:             [Validators.required, Validators.min(1), Validators.max(100)],
96:           ],
97:         })
98:       );
99:     });
100:   }
101: 
102:   cargarEscalas() {
103:     this.evaluacionDocenteService.getCamposActivos().subscribe(
104:       (response: any) => {
105:         this.escalas = response.Data || [];
106:         this.dataSource = new MatTableDataSource(this.escalas);
107:         this.dataSource.paginator = this.paginator;
108:       },
109:       (error) => console.error("Error al cargar las escalas activas", error)
110:     );
111:   }
112: 
113:   obtenerTiposInput() {
114:     const ids = "4668|4674|4672|6686";
115:     this.parametrosService.get(`parametro?query=id__in:${ids}`).subscribe(
116:       (response: any) => (this.tiposInput = response.Data),
117:       (error) => console.error("Error al obtener los tipos de input", error)
118:     );
119:   }
120: 
121:   getTipoEscalaNombre(tipoCampoId: number): string {
122:     const nombres: { [key: number]: string } = {
123:       4674: "Texto",
124:       4668: "Selección de única respuesta",
125:       6686: "Cargar archivo",
126:       4672: "Descargar archivo",
127:     };
128: 
129:     return nombres[tipoCampoId] || "Desconocido";
130:   }
131: 
132:   regresarLista() {
133:     this.isViewingScale = false;
134:     this.activeTab = 0;
135:   }
136: 
137:   mostrarConfirmacion(escala: any): void {
138:     this.evaluacionDocenteService.get(`campo/${escala.Id}`).subscribe(
139:       (response: any) => {
140:         const escalaSeleccionada = response?.Data;
141:         const dialogRef = this.dialog.open(DialogoConfirmacion, {
142:           width: "300px",
143:           data: {
144:             message: `Va a inhabilitar la escala "${escalaSeleccionada?.Nombre}", ¿está segur@ de hacer esto?`,
145:             buttonText: { ok: "Inhabilitar", cancel: "Cancelar" },
146:             escala: escalaSeleccionada,
147:           },
148:         });
149: 
150:         dialogRef.afterClosed().subscribe((result) => {
151:           if (result) {
152:             this.inactivarEscala(escalaSeleccionada);
153:           }
154:         });
155:       },
156:       (error) => console.error("Error al obtener la escala:", error)
157:     );
158:   }
159: 
160:   activarModoCreacion() {
161:     this.isCreating = true;
162:     this.activeTab = 1;
163:   }
164: 
165:   onTipoCampoChange(event: any) {
166:     const tipoSeleccionado = event.value;
167:     this.showMultipleOptions = tipoSeleccionado === "Radio";
168:     this.opciones.clear();
169: 
170:     if (this.showMultipleOptions) {
171:       this.agregarOpcionesPorDefecto();
